import { X, Send, CheckCircle } from 'lucide-react';
import { ContactFormState } from '../types';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose }) => {
